import Forge from './forge.js';
import Forgejo from './forgejo.js';
import Gitea from './gitea.js';
import GitHub from './github.js';
import GitLab from './gitlab.js';

type ForgeType = (new (...args: ConstructorParameters<typeof Forge>) => Forge) & typeof Forge;

/**
 * Map of Forges implementations
 */
export const FORGES: Record<string, ForgeType> = {
    forgejo: Forgejo,
    gitea: Gitea,
    github: GitHub,
    gitlab: GitLab,
};

/**
 * Extract account and notification id.
 *
 * @param id ID generated by Forge.formatID()
 */
export function extractID(id: string): [string, string] {
    const account = id.slice(0, 36);
    const notification = id.slice(37);

    return [account, notification];
}
